    :root{--navy:#16345b;--deep:#0a2039;--blue:#2367a6;--teal:#1f9a9c;--gold:#c6952d;--ink:#182231;--muted:#647286;--line:#dce5ec;--surface:#f4f8fb;--white:#fff}
    *{box-sizing:border-box}body{margin:0;color:var(--ink);background:radial-gradient(circle at 80% 0,rgba(31,154,156,.08),transparent 32%),var(--surface);font-family:Inter,Aptos,"Segoe UI",sans-serif}.shell{display:grid;grid-template-columns:272px minmax(0,1fr);min-height:100vh}.sidebar{position:sticky;top:0;height:100vh;overflow:auto;padding:22px 18px;color:#fff;background:linear-gradient(180deg,var(--navy),var(--deep))}.brand{display:flex;align-items:center;gap:12px;margin-bottom:24px}.brand img{width:48px;height:48px;padding:4px;border-radius:9px;background:#fff;object-fit:contain}.brand strong{display:block;font-size:15px}.brand span{display:block;margin-top:3px;color:#bfd0e2;font-size:11px}.nav{display:grid;gap:7px}.nav>a,.nav summary{display:flex;align-items:center;gap:9px;padding:10px 11px;border-radius:7px;color:#d9e5f1;text-decoration:none;font-size:14px}.nav>a::before,.nav summary::before{content:attr(data-icon);width:18px;text-align:center}.nav>a:hover,.nav summary:hover,.nav details[open]>summary{color:#fff;background:rgba(255,255,255,.14);box-shadow:inset 3px 0 0 var(--gold)}.nav details summary{list-style:none;cursor:pointer}.nav details summary::-webkit-details-marker{display:none}.nav details summary::after{content:"›";margin-left:auto;transform:rotate(90deg);color:var(--gold)}.nav-sub{display:grid;gap:7px;margin:5px 0 8px 32px}.nav-sub a{padding:7px 9px;border-radius:6px;color:#c7d7e8;background:rgba(255,255,255,.06);text-decoration:none;font-size:12px}.nav-sub a:hover,.nav-sub a.active{color:#fff;background:rgba(255,255,255,.14);box-shadow:inset 2px 0 0 var(--gold)}.content{padding:28px clamp(20px,4vw,54px) 50px}.eyebrow{display:block;margin-bottom:8px;color:var(--teal);font-size:12px;font-weight:900;letter-spacing:.1em;text-transform:uppercase}h1{margin:0;color:var(--navy);font-size:clamp(30px,4vw,46px);line-height:1.06}.intro{max-width:850px;margin:12px 0 0;color:var(--muted);font-size:15px;line-height:1.65}.library-meta{display:flex;flex-wrap:wrap;gap:9px;margin-top:18px}.meta-pill{padding:7px 10px;border:1px solid rgba(35,103,166,.13);border-radius:999px;color:#52677b;background:#fff;font-size:11px;font-weight:850}.featured{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(280px,.6fr);gap:22px;margin:24px 0;padding:22px;border:1px solid rgba(15,58,95,.1);border-radius:22px;background:linear-gradient(145deg,#fff,#f2f8fb);box-shadow:0 18px 42px rgba(15,58,95,.11)}.featured-player{position:relative;overflow:hidden;aspect-ratio:16/9;border-radius:16px;background:#07192c}.featured-player iframe{position:absolute;inset:0;width:100%;height:100%;border:0}.featured-copy{display:flex;flex-direction:column;justify-content:center}.featured-label{color:var(--teal);font-size:11px;font-weight:900;letter-spacing:.09em;text-transform:uppercase}.featured h2{margin:8px 0 8px;color:var(--navy);font-size:25px;line-height:1.16}.featured p{margin:0;color:var(--muted);font-size:13px;line-height:1.6}.actions{display:flex;flex-wrap:wrap;gap:9px;margin-top:17px}.action{display:inline-flex;align-items:center;justify-content:center;padding:9px 12px;border-radius:999px;color:#fff;background:var(--blue);font-size:12px;font-weight:900;text-decoration:none;box-shadow:0 8px 18px rgba(35,103,166,.18)}.action.secondary{color:var(--blue);background:#eaf5f8;box-shadow:none}.toolbar{display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin:0 0 18px}.search{flex:1 1 260px;min-height:43px;padding:10px 14px;border:1px solid #d8e3eb;border-radius:12px;background:#fff;color:var(--ink);font:inherit;box-shadow:0 7px 18px rgba(15,58,95,.06)}.filter{padding:9px 12px;border:1px solid rgba(35,103,166,.15);border-radius:999px;color:#52677b;background:#fff;font-size:11px;font-weight:900;cursor:pointer}.filter.active{color:#fff;background:var(--navy)}.section-head{display:flex;justify-content:space-between;gap:15px;align-items:end;margin:22px 0 13px}.section-head h2{margin:0;color:var(--navy);font-size:22px}.section-head span{color:var(--muted);font-size:12px}.video-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:17px}.video-card{position:relative;overflow:hidden;border:1px solid rgba(15,58,95,.1);border-radius:18px;background:#fff;box-shadow:0 13px 30px rgba(15,58,95,.09);transition:transform .16s ease,box-shadow .18s ease,border-color .18s ease}.video-card:hover,.video-card:focus-within{transform:translateY(-4px);border-color:rgba(35,103,166,.28);box-shadow:0 19px 38px rgba(15,58,95,.15)}.thumb-button{position:relative;display:block;width:100%;padding:0;border:0;background:#0b1e32;cursor:pointer}.thumb{display:block;width:100%;aspect-ratio:9/16;max-height:390px;object-fit:cover;object-position:center}.play{position:absolute;left:50%;top:50%;display:grid;place-items:center;width:52px;height:52px;border:1px solid rgba(255,255,255,.72);border-radius:50%;color:#fff;background:rgba(10,32,57,.78);box-shadow:0 9px 23px rgba(0,0,0,.25);font-size:18px;transform:translate(-50%,-50%);transition:transform .16s ease,background .16s ease}.thumb-button:hover .play,.thumb-button:focus-visible .play{background:var(--blue);transform:translate(-50%,-50%) scale(1.08)}.duration{position:absolute;right:9px;bottom:9px;padding:4px 7px;border-radius:999px;color:#fff;background:rgba(7,25,44,.82);font-size:10px;font-weight:900}.video-copy{padding:15px}.video-copy h3{margin:0;color:var(--navy);font-size:16px}.video-copy p{min-height:34px;margin:6px 0 0;color:var(--muted);font-size:11px;line-height:1.5}.video-foot{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:12px}.format{padding:5px 8px;border-radius:999px;color:#0f6f70;background:#e6f5f3;font-size:9px;font-weight:900;letter-spacing:.05em;text-transform:uppercase}.vimeo-link{color:var(--blue);font-size:10px;font-weight:900;text-decoration:none}.empty{grid-column:1/-1;padding:38px;border:1px dashed #c8d7e2;border-radius:18px;text-align:center;color:var(--muted);background:#fff}.video-card[hidden],.empty[hidden]{display:none}.download-note{margin:22px 0 0;padding:14px 16px;border-left:4px solid var(--gold);border-radius:0 12px 12px 0;color:#5c6875;background:#fff9ec;font-size:12px;line-height:1.55}.modal{position:fixed;inset:0;z-index:30;display:grid;place-items:center;padding:22px;background:rgba(4,16,29,.82);backdrop-filter:blur(10px)}.modal[hidden]{display:none}.modal-dialog{width:min(94vw,520px);padding:16px;border:1px solid rgba(255,255,255,.18);border-radius:20px;background:#102a46;box-shadow:0 28px 80px rgba(0,0,0,.45)}.modal-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px;color:#fff}.modal-head h2{margin:0;font-size:17px}.close{width:36px;height:36px;border:1px solid rgba(255,255,255,.25);border-radius:50%;color:#fff;background:rgba(255,255,255,.08);font-size:20px;cursor:pointer}.modal-player{position:relative;overflow:hidden;width:min(100%,360px);margin:auto;aspect-ratio:9/16;border-radius:14px;background:#061727}.modal-player iframe{position:absolute;inset:0;width:100%;height:100%;border:0}@@media(max-width:900px){.shell{grid-template-columns:1fr}.sidebar{position:static;height:auto}.nav{grid-template-columns:repeat(2,minmax(0,1fr))}.nav details{grid-column:1/-1}.featured{grid-template-columns:1fr}.content{padding:24px 18px 40px}}@@media(max-width:520px){.video-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.video-card .video-copy{padding:12px}.video-copy p{display:none}.thumb{max-height:none}.featured{padding:15px}.modal{padding:10px}}
