  <div class="modal" id="videoModal" role="dialog" aria-modal="true" aria-labelledby="modalTitle" hidden><div class="modal-dialog"><div class="modal-head"><h2 id="modalTitle">Video</h2><button class="close" id="closeModal" type="button" aria-label="Close video">×</button></div><div class="modal-player"><iframe id="modalFrame" src="about:blank" allow="autoplay; fullscreen; picture-in-picture; clipboard-write; encrypted-media; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen title="Selected Global Network video"></iframe></div></div></div>
  <script>
    const search = document.getElementById('videoSearch');
    const cards = [...document.querySelectorAll('.video-card')];
    const filters = [...document.querySelectorAll('.filter')];
    const empty = document.getElementById('emptyState');
    const modal = document.getElementById('videoModal');
    const frame = document.getElementById('modalFrame');
    const modalTitle = document.getElementById('modalTitle');
    const closeModal = document.getElementById('closeModal');
    let activeFormat = 'all';
    function updateLibrary(){const query=search.value.trim().toLowerCase();let visible=0;cards.forEach(card=>{const matchFormat=activeFormat==='all'||card.dataset.format===activeFormat;const matchSearch=!query||card.dataset.search.includes(query);card.hidden=!(matchFormat&&matchSearch);if(!card.hidden)visible+=1});empty.hidden=visible!==0}
    search.addEventListener('input',updateLibrary);
    filters.forEach(button=>button.addEventListener('click',()=>{activeFormat=button.dataset.format;filters.forEach(item=>item.classList.toggle('active',item===button));updateLibrary()}));
    document.querySelectorAll('.thumb-button').forEach(button=>button.addEventListener('click',()=>{modalTitle.textContent=button.dataset.title;frame.src=`https://player.vimeo.com/video/${button.dataset.videoId}?h=${button.dataset.hash}&autoplay=1&title=0&byline=0&portrait=0`;modal.hidden=false;document.body.style.overflow='hidden';closeModal.focus()}));
    function closePlayer(){modal.hidden=true;frame.src='about:blank';document.body.style.overflow=''}
    closeModal.addEventListener('click',closePlayer);
    modal.addEventListener('click',event=>{if(event.target===modal)closePlayer()});
    document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!modal.hidden)closePlayer()});
  </script>
